#!/usr/bin/env bash
# The raw-pointer scans of abla/http (request parse, request line version, query lookup) against their checked twins on generated bytes
# (#1139 area 4; tests/cases/http-native-scan/main.ab): built under each compile-time tier, the interpreter runs the checked versions and the
# JIT and the program itself the native ones, and the three must agree. Usage: tools/test-http-native-scan.sh [compiler]
set -euo pipefail
compiler=${1:-build/ablac}
[[ $compiler == /* || $compiler != */* ]] || compiler="$PWD/$compiler"
root=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
cd "$root"
out=build/http-native-scan
rm -rf "$out"
mkdir -p "$out"
for tier in interp jit; do
    ABLA_COMPILE_EVAL=$tier "$compiler" build tests/cases/http-native-scan/main.ab -o "$out/scan-$tier" --fast --no-cache
    result=$("$root/tools/run-limited.sh" "$out/scan-$tier") || { echo "http-native-scan ($tier): $result" >&2; exit 1; }
    [[ $result == 'http-native-scan ok' ]] || { echo "http-native-scan ($tier): $result" >&2; exit 1; }
done
echo "http-native-scan ok: the native and checked scans agree on generated requests (interpreter and JIT tiers)"
